import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib

app = Flask(__name__)
UPLOAD_DIR = '/var/lib/reports/uploads'
OUTPUT_DIR = '/var/lib/reports/output'
ALLOWED_EXTENSIONS = {'txt', 'csv', 'json', 'xml'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_report_name(name):
    # Remove directory traversal attempts
    name = name.replace('..', '').replace('/', '').replace('\\', '')
    # Allow alphanumeric, dash, underscore, dot
    return ''.join(c for c in name if c.isalnum() or c in '-_.')

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    """Generate a formatted report from uploaded data using system pandoc."""
    if 'datafile' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    datafile = request.files['datafile']
    if not datafile.filename or not allowed_file(datafile.filename):
        return jsonify({'error': 'Invalid file type'}), 400

    report_title = request.form.get('title', 'Untitled Report')
    output_format = request.form.get('format', 'pdf')
    template_name = request.form.get('template', 'default')

    # Validate output format
    if output_format not in ('pdf', 'html', 'docx'):
        return jsonify({'error': 'Unsupported format'}), 400

    # Save uploaded file
    safe_name = secure_filename(datafile.filename)
    upload_path = os.path.join(UPLOAD_DIR, safe_name)
    datafile.save(upload_path)

    # Generate unique output filename
    file_hash = hashlib.md5(safe_name.encode() + report_title.encode()).hexdigest()[:12]
    output_filename = f"report_{file_hash}.{output_format}"
    output_path = os.path.join(OUTPUT_DIR, output_filename)

    # Build pandoc command for report generation
    # Template path is constructed from user input
    template_path = f"/var/lib/reports/templates/{sanitize_report_name(template_name)}.tmpl"

    cmd = f'pandoc {upload_path} -o {output_path} --metadata title="{report_title}" --template={template_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=OUTPUT_DIR
        )
        if result.returncode != 0:
            app.logger.error(f"Pandoc error: {result.stderr.decode()}")
            return jsonify({'error': 'Report generation failed', 'details': result.stderr.decode()[:200]}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504
    except Exception as e:
        app.logger.error(f"Unexpected error: {str(e)}")
        return jsonify({'error': 'Internal error'}), 500
    finally:
        # Cleanup upload
        if os.path.exists(upload_path):
            os.unlink(upload_path)

    return jsonify({
        'status': 'success',
        'download_url': f'/api/reports/download/{output_filename}'
    })

@app.route('/api/reports/download/<filename>')
def download_report(filename):
    safe = secure_filename(filename)
    path = os.path.join(OUTPUT_DIR, safe)
    if not os.path.exists(path):
        return jsonify({'error': 'Not found'}), 404
    return send_file(path, as_attachment=True)

@app.route('/api/reports/templates', methods=['GET'])
def list_templates():
    templates_dir = '/var/lib/reports/templates'
    templates = [f.replace('.tmpl', '') for f in os.listdir(templates_dir) if f.endswith('.tmpl')]
    return jsonify({'templates': templates})

@app.route('/api/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
